const p = $json.body || {};
if (!p.company) throw new Error('company is required');
const q = [p.company, p.city, p.country].filter(Boolean).join(' ');
return [{json:{
  ...p,
  searchQuery:q,
  searchUrl:'https://www.google.com/search?q='+encodeURIComponent(q)
}}];

const src = $('Prepare Enrichment Query').first().json;
const html = String($input.first().json || '');

function decode(s=''){return s.replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"');}
function pickPhone(t){
  const m=t.match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/);
  return m?m[0]:'';
}
function pickEmail(t){
  const m=t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m?m[0]:'';
}
function pickWebsite(t){
  const urls=[...t.matchAll(/https?:\/\/[^\s"'<>]+/g)].map(m=>decode(m[0]));
  const bad=/google\.|gstatic\.|youtube\.|facebook\.|instagram\.|linkedin\.|yellowpages\.|yelp\.|mapquest\.|bing\./i;
  return urls.find(u=>!bad.test(u))||'';
}
const phone = src.phone || pickPhone(html);
const email = src.email || pickEmail(html);
const website = src.website || pickWebsite(html);

let confidence=20;
const sources=['OpenStreetMap'];
if(phone){confidence+=25;sources.push('Public web search');}
if(email){confidence+=25;if(!sources.includes('Public web search'))sources.push('Public web search');}
if(website){confidence+=25;if(!sources.includes('Public web search'))sources.push('Public web search');}

let verification_status='Needs verification';
if(confidence>=70 && (phone||email) && website) verification_status='Verified';
else if(!(phone||email)) verification_status='Not contactable';

return [{json:{
  ...src,
  phone,
  email,
  website,
  sources,
  confidence:Math.min(100,confidence),
  verification_status,
  contactable:Boolean(phone||email),
  verified_at:new Date().toISOString()
}}];
